-static void detect_lan_ip(char *out, size_t out_size)
-{
-    snprintf(out, out_size, "127.0.0.1");
-#ifdef __vita__
-    SceNetCtlInfo info;
-    memset(&info, 0, sizeof(info));
-    if (sceNetCtlInetGetInfo(SCE_NETCTL_INFO_GET_IP_ADDRESS, &info) == 0 && info.ip_address[0] != '\0') {
